def make_grid(h,w,bg,boxes):
    g=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in boxes:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1): g[r][c]=color
    return g
def expected(g,boxes):
    z=[row[:] for row in g]
    for color,r0,r1,c0,c1 in boxes:
        fill=7 if (r1-r0-1)%2 else 2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1): z[r][c]=fill
    return z
b1=[(5,1,5,3,7),(1,5,11,11,17),(1,18,22,3,7),(3,20,23,15,18),(5,24,26,10,12)]
